74:static void greedy_argmax_kernel(int64_t* __restrict__ output,
75:                                 const float* __restrict__ logits,
76:                                 const int64_t batch_size,
77:                                 const int64_t vocab_size) {
78:  constexpr int VEC_ELEM_NUM = vec_op::FP32Vec16::VEC_ELEM_NUM;
79:  const int64_t vec_end = vocab_size - (vocab_size % VEC_ELEM_NUM);
80:
81:#pragma omp parallel for schedule(static)
82:  for (int64_t b = 0; b < batch_size; ++b) {
83:    const float* row = logits + b * vocab_size;
84:
85:    // Vector max has no consistent NaN rule, so NaNs are caught via the sum:
86:    // any NaN (or inf + -inf, a harmless false positive) makes it NaN.
87:    vec_op::FP32Vec16 vmax(-std::numeric_limits<float>::infinity());
88:    vec_op::FP32Vec16 vsum(0.0f);
89:    for (int64_t i = 0; i < vec_end; i += VEC_ELEM_NUM) {
90:      vec_op::FP32Vec16 v(row + i);
91:      vmax = vmax.max(v);
92:      vsum = vsum + v;
93:    }
94:    float best_val = vmax.reduce_max();
95:    bool maybe_nan = std::isnan(vsum.reduce_sum());
96:    for (int64_t i = vec_end; i < vocab_size; ++i) {
97:      maybe_nan |= std::isnan(row[i]);
98:      if (row[i] > best_val) {
99:        best_val = row[i];
100:      }
101:    }
102:
103:    int64_t best_idx = -1;
104:    if (maybe_nan) {
105:      // torch.argmax treats NaN as the maximum: return the first NaN.
106:      for (int64_t i = 0; i < vocab_size; ++i) {
107:        if (std::isnan(row[i])) {
108:          best_idx = i;
109:          break;
110:        }
111:      }
112:    }
113:    if (best_idx < 0) {
114:      best_idx = 0;
115:      for (int64_t i = 0; i < vocab_size; ++i) {
116:        if (row[i] == best_val) {
117:          best_idx = i;
118:          break;
119:        }
120:      }
121:    }
122:    output[b] = best_idx;
123:  }
124:}
125:
126:}  // namespace
